<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/bootstrap.php';
require_once dirname(__DIR__) . '/includes/upload.php';
require_admin();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT);
$product = ['name_fa'=>'','name_en'=>'','description'=>'','ingredients'=>'','price'=>'','category_id'=>'','image'=>null,'is_featured'=>0,'badge_vegan'=>0,'badge_sugar_free'=>0,'badge_diet'=>0,'caffeine_level'=>0,'is_available'=>1,'is_visible'=>1,'sort_order'=>0];
if ($id) { $s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('محصول پیدا نشد.');} }
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf_verify();
  $priceRaw=trim((string)($_POST['price']??''));
  $data=['name_fa'=>trim((string)($_POST['name_fa']??'')),'name_en'=>trim((string)($_POST['name_en']??'')),'description'=>trim((string)($_POST['description']??'')),'ingredients'=>trim((string)($_POST['ingredients']??'')),'price'=>$priceRaw===''?null:filter_var($priceRaw,FILTER_VALIDATE_INT),'category_id'=>filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT),'sort_order'=>filter_var($_POST['sort_order']??0,FILTER_VALIDATE_INT),'is_featured'=>request_bool('is_featured'),'badge_vegan'=>request_bool('badge_vegan'),'badge_sugar_free'=>request_bool('badge_sugar_free'),'badge_diet'=>request_bool('badge_diet'),'caffeine_level'=>min(3,max(0,(int)($_POST['caffeine_level']??0))),'is_available'=>request_bool('is_available'),'is_visible'=>request_bool('is_visible')];
  if($data['name_fa']===''||mb_strlen($data['name_fa'])>150)$errors[]='نام فارسی الزامی و حداکثر ۱۵۰ حرف است.';
  if($data['price']!==null&&($data['price']===false||$data['price']<0))$errors[]='قیمت معتبر وارد کنید یا برای «استعلام قیمت» خالی بگذارید.';
  if(!$data['category_id'])$errors[]='دسته‌بندی را انتخاب کنید.';
  if(mb_strlen($data['description'])>500)$errors[]='توضیحات حداکثر ۵۰۰ حرف باشد.';
  if(mb_strlen($data['ingredients'])>700)$errors[]='ترکیبات حداکثر ۷۰۰ حرف باشد.';
  $cat=db()->prepare('SELECT COUNT(*) FROM categories WHERE id=?');$cat->execute([$data['category_id']]);if(!$cat->fetchColumn())$errors[]='دسته‌بندی معتبر نیست.';
  $newImage=null;
  if(!$errors){try{$newImage=upload_product_image($_FILES['image']??[]);}catch(RuntimeException $e){$errors[]=$e->getMessage();}}
  if(!$errors){
    $image=$newImage?:$product['image'];
    if(!$newImage&&isset($_POST['remove_image'])&&$product['image']){$image=null;delete_image($product['image']);}
    if($id){$q=db()->prepare('UPDATE products SET name_fa=?,name_en=?,description=?,ingredients=?,price=?,category_id=?,image=?,is_featured=?,badge_vegan=?,badge_sugar_free=?,badge_diet=?,caffeine_level=?,is_available=?,is_visible=?,sort_order=? WHERE id=?');$q->execute([$data['name_fa'],$data['name_en']?:null,$data['description']?:null,$data['ingredients']?:null,$data['price'],$data['category_id'],$image,$data['is_featured'],$data['badge_vegan'],$data['badge_sugar_free'],$data['badge_diet'],$data['caffeine_level'],$data['is_available'],$data['is_visible'],$data['sort_order'],$id]);if($newImage&&$product['image'])delete_image($product['image']);flash('success','محصول ویرایش شد.');}
    else{$q=db()->prepare('INSERT INTO products(name_fa,name_en,description,ingredients,price,category_id,image,is_featured,badge_vegan,badge_sugar_free,badge_diet,caffeine_level,is_available,is_visible,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$data['name_fa'],$data['name_en']?:null,$data['description']?:null,$data['ingredients']?:null,$data['price'],$data['category_id'],$image,$data['is_featured'],$data['badge_vegan'],$data['badge_sugar_free'],$data['badge_diet'],$data['caffeine_level'],$data['is_available'],$data['is_visible'],$data['sort_order']]);flash('success','محصول جدید اضافه شد.');}
    redirect('admin/products.php');
  }
  $product=array_merge($product,$data);
}
$categories=db()->query('SELECT id,name_fa,is_active FROM categories ORDER BY sort_order,id')->fetchAll();$adminTitle=$id?'ویرایش محصول':'محصول جدید';require __DIR__.'/_header.php';
?><?php if($errors):?><div class="alert error" role="alert"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" enctype="multipart/form-data" class="panel edit-form"><?=csrf_field()?><?php if($id):?><input type="hidden" name="id" value="<?=$id?>"><?php endif;?><div class="form-grid"><label>نام فارسی *<input name="name_fa" maxlength="150" required value="<?=e((string)$product['name_fa'])?>"></label><label>نام انگلیسی کوتاه<input name="name_en" maxlength="150" dir="ltr" value="<?=e((string)$product['name_en'])?>" placeholder="Iced Latte"></label><label class="wide">توضیح کوتاه<textarea name="description" maxlength="500" rows="2"><?=e((string)$product['description'])?></textarea></label><label class="wide">ترکیبات محصول<textarea name="ingredients" maxlength="700" rows="3" placeholder="مثلاً: اسپرسو، شیر، یخ و سیروپ وانیل"><?=e((string)$product['ingredients'])?></textarea><small>تنها در صورت تکمیل، با دکمه «ترکیبات» به مشتری نشان داده می‌شود.</small></label><label>قیمت (تومان)<input type="number" name="price" min="0" step="1000" value="<?=e((string)$product['price'])?>"><small>برای نمایش «استعلام قیمت» خالی بگذارید.</small></label><label>دسته‌بندی *<select name="category_id" required><option value="">انتخاب کنید</option><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>" <?=$product['category_id']==$c['id']?'selected':''?>><?=e($c['name_fa'])?><?=$c['is_active']?'':' (غیرفعال)'?></option><?php endforeach;?></select></label><label>ترتیب نمایش<input type="number" name="sort_order" min="0" value="<?=e((string)$product['sort_order'])?>"></label><label>میزان کافئین<select name="caffeine_level"><option value="0">نمایش داده نشود</option><option value="1" <?=$product['caffeine_level']==1?'selected':''?>>کم</option><option value="2" <?=$product['caffeine_level']==2?'selected':''?>>متوسط</option><option value="3" <?=$product['caffeine_level']==3?'selected':''?>>زیاد</option></select></label><label>تصویر محصول<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPG، PNG یا WEBP تا <?=fa_digits((string)round(MAX_UPLOAD_BYTES/1000000,1))?> مگابایت</small></label><?php if($product['image']):?><div class="image-current"><img src="<?=url('uploads/'.rawurlencode($product['image']))?>" alt="تصویر فعلی"><label class="check"><input type="checkbox" name="remove_image"> حذف تصویر فعلی</label></div><?php endif;?></div><fieldset class="badge-options"><legend>نشان‌ها و ویژگی‌ها</legend><label class="check"><input type="checkbox" name="is_featured" value="1" <?=$product['is_featured']?'checked':''?>> پیشنهاد امروز</label><label class="check"><input type="checkbox" name="badge_vegan" value="1" <?=$product['badge_vegan']?'checked':''?>> وگان</label><label class="check"><input type="checkbox" name="badge_sugar_free" value="1" <?=$product['badge_sugar_free']?'checked':''?>> بدون شکر</label><label class="check"><input type="checkbox" name="badge_diet" value="1" <?=$product['badge_diet']?'checked':''?>> رژیمی</label></fieldset><div class="switches"><label class="check"><input type="checkbox" name="is_available" value="1" <?=$product['is_available']?'checked':''?>> موجود است</label><label class="check"><input type="checkbox" name="is_visible" value="1" <?=$product['is_visible']?'checked':''?>> در منو نمایش داده شود</label></div><div class="form-actions"><button class="btn primary" type="submit">ذخیره محصول</button><a class="btn" href="<?=url('admin/products.php')?>">انصراف</a></div></form><?php require __DIR__.'/_footer.php';?>
